--- a/core/spring-boot/src/main/java/org/springframework/boot/ansi/AnsiPropertySource.java
+++ b/core/spring-boot/src/main/java/org/springframework/boot/ansi/AnsiPropertySource.java
@@ -16,11 +16,10 @@

 package org.springframework.boot.ansi;

-import java.util.ArrayList;
-import java.util.Collections;
 import java.util.EnumSet;
+import java.util.HashMap;
 import java.util.List;
-import java.util.Set;
+import java.util.Map;
 import java.util.function.IntFunction;

 import org.jspecify.annotations.Nullable;
@@ -47,20 +46,13 @@ import org.springframework.util.StringUtils;
  */
 public class AnsiPropertySource extends PropertySource<AnsiElement> {

-	private static final Iterable<Mapping> MAPPINGS;
-
-	static {
-		List<Mapping> mappings = new ArrayList<>();
-		mappings.add(new EnumMapping<>("AnsiStyle.", AnsiStyle.class));
-		mappings.add(new EnumMapping<>("AnsiColor.", AnsiColor.class));
-		mappings.add(new Ansi8BitColorMapping("AnsiColor.", Ansi8BitColor::foreground));
-		mappings.add(new EnumMapping<>("AnsiBackground.", AnsiBackground.class));
-		mappings.add(new Ansi8BitColorMapping("AnsiBackground.", Ansi8BitColor::background));
-		mappings.add(new EnumMapping<>("Ansi.", AnsiStyle.class));
-		mappings.add(new EnumMapping<>("Ansi.", AnsiColor.class));
-		mappings.add(new EnumMapping<>("Ansi.BG_", AnsiBackground.class));
-		MAPPINGS = Collections.unmodifiableList(mappings);
-	}
+	private static final List<Mapping> MAPPINGS = List.of(new EnumMapping<>("AnsiStyle.", AnsiStyle.class),
+			new EnumMapping<>("AnsiColor.", AnsiColor.class),
+			new Ansi8BitColorMapping("AnsiColor.", Ansi8BitColor::foreground),
+			new EnumMapping<>("AnsiBackground.", AnsiBackground.class),
+			new Ansi8BitColorMapping("AnsiBackground.", Ansi8BitColor::background),
+			new EnumMapping<>("Ansi.", AnsiStyle.class), new EnumMapping<>("Ansi.", AnsiColor.class),
+			new EnumMapping<>("Ansi.BG_", AnsiBackground.class));

 	private final boolean encode;

@@ -115,21 +107,20 @@ public class AnsiPropertySource extends PropertySource<AnsiElement> {
 	 */
 	private static class EnumMapping<E extends Enum<E> & AnsiElement> extends Mapping {

-		private final Set<E> enums;
+		private final Map<String, E> elements;

 		EnumMapping(String prefix, Class<E> enumType) {
 			super(prefix);
-			this.enums = EnumSet.allOf(enumType);
+			Map<String, E> elements = new HashMap<>();
+			for (E candidate : EnumSet.allOf(enumType)) {
+				elements.put(candidate.name(), candidate);
+			}
+			this.elements = elements;
 		}

 		@Override
 		@Nullable AnsiElement getElement(String postfix) {
-			for (Enum<?> candidate : this.enums) {
-				if (candidate.name().equals(postfix)) {
-					return (AnsiElement) candidate;
-				}
-			}
-			return null;
+			return this.elements.get(postfix);
 		}

 	}
